#!/usr/bin/env python3
"""Portable controls for run_string_binding.py before the driver is frozen.

These checks do not build or execute Woozy Source.  They exercise the two new
test-driver-facing behaviours in the harness:

* the candidate API metadata must publish source_name and generated from the
  real driver JSON (no reconstructed ``_f`` values);
* the five probe names and their exact UTF-8/text assertions remain fixed;
* process success is an int exit plus strict booleans;
* CLI/API generated bytes must match before the host is copied;
* candidate evidence refuses a non-empty output directory.
"""
from __future__ import annotations

import json
import sys
import tempfile
import unittest
from pathlib import Path

sys.dont_write_bytecode = True
sys.path.insert(0, str(Path(__file__).resolve().parent))
import run_string_binding as runner  # noqa: E402


def symbols(count=5):
    return [
        {'symbol': 100 + index, 'source_name': name,
         'generated': f'_f{100 + index}'}
        for index, name in enumerate(sorted(runner.PROBE_NAMES))
    ] + [{'symbol': 200, 'source_name': 'main', 'generated': '_f200'}]


def record(exit_code=0, **changes):
    return dict(dict(label='portable fixture', exit=exit_code,
                     timed_out=False, cleanup_complete=True,
                     abandoned_pipes=False, stdout='', stderr=''), **changes)


class Controls(unittest.TestCase):
    def test_strict_process_success(self):
        runner.require_ok(record())
        for key, values in {
                'exit': [False, True, 0.0, None, -9],
                'timed_out': [0, None, True],
                'cleanup_complete': [1, None, False],
                'abandoned_pipes': [0, None, True]}.items():
            for value in values:
                with self.subTest(key=key, value=value):
                    with self.assertRaises(RuntimeError):
                        runner.require_ok(record(**{key: value}))

    def test_published_symbols_only(self):
        probes = runner.symbol_probes(symbols())
        self.assertEqual(set(probes), runner.PROBE_NAMES)
        self.assertTrue(all(value.startswith('_f') for value in probes.values()))
        # A guessed _f mapping without published source_name is not metadata.
        broken = [{'symbol': 1, 'generated': '_f1'}]
        with self.assertRaisesRegex(RuntimeError, 'source_name'):
            runner.symbol_probes(broken)
        missing = [item for item in symbols()
                   if item['source_name'] != 'probe_host_vec']
        with self.assertRaisesRegex(RuntimeError, 'probe symbols differ'):
            runner.symbol_probes(missing)
        extra = symbols() + [{'symbol': 300, 'source_name': 'probe_host_extra',
                              'generated': '_f300'}]
        with self.assertRaisesRegex(RuntimeError, 'probe symbols differ'):
            runner.symbol_probes(extra)

    def test_driver_json_metadata(self):
        document = {'status': 'ok', 'entry': 200, 'symbols': symbols()}
        api_dir = Path('/nonexistent-api-dir')
        with tempfile.TemporaryDirectory() as temp:
            metadata, parsed = runner.read_api_metadata(
                'driver', api_dir,
                record(stdout=json.dumps(document)))
            self.assertEqual(parsed, document)
            self.assertEqual(metadata['symbol_count'], len(symbols()))
            self.assertEqual(metadata['source'], 'stdout')
            self.assertEqual(len(metadata['sha256']), 64)

    def test_generated_bytes_before_host(self):
        with tempfile.TemporaryDirectory() as temp:
            left = Path(temp) / 'cli'
            right = Path(temp) / 'api'
            left.mkdir()
            right.mkdir()
            for directory in (left, right):
                (directory / 'program.py').write_text('print(1)\n')
                (directory / 'langrt.py').write_text('RUNTIME = 1\n')
            runner.compare_entries(left, right, 'portable')
            (right / 'langrt.py').write_text('RUNTIME = 2\n')
            with self.assertRaisesRegex(RuntimeError, 'langrt.py'):
                runner.compare_entries(left, right, 'portable')

    def test_candidate_output_must_be_fresh(self):
        with tempfile.TemporaryDirectory() as temp:
            out = Path(temp) / 'evidence'
            out.mkdir()
            (out / 'old.json').write_text('{}\n')
            with self.assertRaisesRegex(RuntimeError, 'refusing to overwrite'):
                runner.prepare_output(out, strict=True)
            runner.prepare_output(out, strict=False)
            self.assertTrue((out / 'old.json').is_file())


if __name__ == '__main__':
    suite = unittest.defaultTestLoader.loadTestsFromTestCase(Controls)
    result = unittest.TextTestRunner(verbosity=2).run(suite)
    print('CONTROLS ' + ('passed' if result.wasSuccessful() else 'failed'))
    raise SystemExit(0 if result.wasSuccessful() else 1)
